begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','messages','Message persistence exists');
insert into auth.users(id,email) select ('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'message-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.memberships(user_id,role) select ('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=3 then 'admin' else 'member' end::public.member_role from generate_series(1,4) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('20500000-0000-4000-8000-000000000002','Message pilot','KPAO','licensed');
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('20510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','Message C172',1,case when n=2 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,3) n;
insert into public.flight_recipients(flight_id,user_id) values('20510000-0000-4000-8000-000000000002','20500000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) select ('20520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000002' from generate_series(1,3) n;
update public.flight_requests set status='accepted' where id::text like '20520000%';
insert into public.conversations(id,flight_request_id,owner_id,requester_id) select ('20530000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20500000-0000-4000-8000-000000000001','20500000-0000-4000-8000-000000000002' from generate_series(1,3) n;
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.store(body text default 'Plain message',sender integer default 1,thread integer default 1) returns uuid language sql as $$insert into public.messages(conversation_id,sender_id,body,created_at) values(('20530000-0000-4000-8000-'||lpad(thread::text,12,'0'))::uuid,('20500000-0000-4000-8000-'||lpad(sender::text,12,'0'))::uuid,body,'2000-01-01') returning id;$$;
select ok(not has_table_privilege('anon','public.messages','SELECT'),'Anonymous history denied');
select ok(not has_table_privilege('authenticated','public.messages','INSERT,UPDATE,DELETE'),'Direct member mutations stay closed until guarded send flow');
select ok(not has_table_privilege('service_role','public.messages','INSERT,UPDATE,DELETE'),'No privileged message write API exposed');
select is((select relrowsecurity from pg_class where oid='public.messages'::regclass),true,'Messages have RLS before exposure');
select ok(pg_get_indexdef('public.messages_conversation_order'::regclass) like '%(conversation_id, created_at, id)%','Conversation/time/UUID keyset ordering index exists');
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.store()$$,'42501',null,'Even privileged insert requires explicit authenticated sender');
select pg_temp.actor(1);
select throws_ok($$select pg_temp.store(sender=>2)$$,'42501',null,'Sender spoofing rejected by persistence');
select throws_ok($$select pg_temp.store(body=>'')$$,'23514',null,'Empty body rejected');
select throws_ok($$select pg_temp.store(body=>E' \t\n\r')$$,'23514',null,'Whitespace-only body rejected');
select throws_ok($$select pg_temp.store(body=>repeat('x',4001))$$,'23514',null,'Oversized text rejected');
select lives_ok($$select pg_temp.store(body=>repeat('😀',4000))$$,'4,000 Unicode characters accepted without byte-count truncation');
select lives_ok($$select pg_temp.store(body=>E'  <script>plain text</script>\nSecond line  ')$$,'Plain markup-looking text and spacing are retained');
select is((select body from public.messages where conversation_id='20530000-0000-4000-8000-000000000001' and length(body)<100),E'  <script>plain text</script>\nSecond line  ','Persistence does not render or rewrite text');
select ok((select bool_and(m.created_at>=c.created_at and m.created_at<>'2000-01-01'::timestamptz) from public.messages m join public.conversations c on c.id=m.conversation_id where c.id='20530000-0000-4000-8000-000000000001'),'Server timestamps ignore forged chronology and do not predate conversation');
select lives_ok($$select pg_temp.store(thread=>2)$$,'Private conversation stores participant message');
select throws_ok($$select pg_temp.store(thread=>99)$$,'42501',null,'Missing conversation denied without a write');
select throws_ok($$update public.messages set body='Edited' where conversation_id='20530000-0000-4000-8000-000000000001'$$,'23514',null,'Privileged message edits rejected');
select throws_ok($$update public.messages set created_at='1999-01-01' where conversation_id='20530000-0000-4000-8000-000000000001'$$,'23514',null,'Ordering metadata immutable');
select throws_ok($$update public.messages set conversation_id='20530000-0000-4000-8000-000000000002' where conversation_id='20530000-0000-4000-8000-000000000001'$$,'23514',null,'Messages cannot be moved between conversations');
select throws_ok($$delete from public.conversations where id='20530000-0000-4000-8000-000000000001'$$,'23503',null,'Conversation cannot cascade-delete shared messages');
set local role authenticated;
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),3,'Posting pilot reads pair history');
select throws_ok($$select pg_temp.store()$$,'42501',null,'Authenticated direct sends denied before VOLO-81');
select pg_temp.actor(2);
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),3,'Joining pilot reads pair history');
select pg_temp.actor(3);
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),0,'Unrelated admin has no history bypass');
select pg_temp.actor(5);
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),0,'Missing membership cannot read history');
reset role;
select pg_temp.actor(3);
select throws_ok($$select pg_temp.store(sender=>3)$$,'42501',null,'Unrelated admin cannot persist messages');
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id='20500000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.actor(2);
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),0,'Disabled viewer loses history with retained identity');
reset role;
select pg_temp.actor(1);
select throws_ok($$select pg_temp.store()$$,'42501',null,'Disabled counterpart blocks persistence');
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='20500000-0000-4000-8000-000000000002';
set local role authenticated;
select public.change_flight_recipient('20510000-0000-4000-8000-000000000002','20500000-0000-4000-8000-000000000002',false);
select pg_temp.actor(2);
select is((select count(*)::integer from public.messages where conversation_id='20530000-0000-4000-8000-000000000002'),1,'Removed PRIVATE recipient retains message history');
select is((select count(*)::integer from public.flights where id='20510000-0000-4000-8000-000000000002'),0,'Message history grants no current PRIVATE flight access');
select public.withdraw_flight_request('20510000-0000-4000-8000-000000000001','20520000-0000-4000-8000-000000000001');
reset role;
select throws_ok($$select pg_temp.store(sender=>2)$$,'42501',null,'Withdrawal blocks new persisted messages');
select throws_ok($$select pg_temp.store(sender=>2,thread=>2)$$,'42501',null,'PRIVATE removal blocks new persisted messages');
select pg_temp.actor(1);
select public.cancel_flight('20510000-0000-4000-8000-000000000003');
select throws_ok($$select pg_temp.store(thread=>3)$$,'42501',null,'Flight cancellation blocks new persisted messages');
set local role authenticated;
select is((select count(*)::integer from public.messages where conversation_id::text like '20530000%'),3,'Closed threads retain exact existing history');
select results_eq($$with cursor as (select created_at,id from public.messages where conversation_id='20530000-0000-4000-8000-000000000001' order by created_at,id limit 1) select body from public.messages m cross join cursor c where m.conversation_id='20530000-0000-4000-8000-000000000001' and (m.created_at,m.id)>(c.created_at,c.id) order by m.created_at,m.id$$,$$values(E'  <script>plain text</script>\nSecond line  ')$$,'Tuple cursor returns next message once without duplicating first page');
reset role;
select * from finish();
rollback;
